const Modal=({title,onClose,children}:any)=><div className='fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/40 sm:p-4' onClick={onClose}><div className='w-full sm:max-w-lg max-h-[92vh] overflow-y-auto rounded-t-3xl sm:rounded-3xl bg-white dark:bg-zinc-900 text-slate-900 dark:text-slate-100 p-6 pb-[calc(1.5rem+env(safe-area-inset-bottom))]' onClick={e=>e.stopPropagation()}><div className='flex items-center justify-between mb-4'><h2 className='text-xl font-bold tracking-tight'>{title}</h2><button onClick={onClose} className='h-8 w-8 grid place-items-center rounded-full bg-slate-100 dark:bg-zinc-800'><Icon n='x' size={16}/></button></div>{children}</div></div>;
